    "recipe_ru": "<p>Замесите мягкое тесто и дайте ему отдохнуть.</p><p>Разомните вареную фасоль с луком, грецкими орехами и зеленью.</p><p>Наполните лепешки начинкой, раскатайте и выпекайте на противне.</p><p>Подавайте с маринованными овощами.</p>",
